const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const required = [
  "index.html",
  "cars.html",
  "parts.html",
  "services.html",
  "about.html",
  "contact.html",
  "assets/css/styles.css",
  "assets/js/main.js",
  "vercel.json",
];

for (const rel of required) {
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) {
    console.error("Missing required file:", rel);
    process.exit(1);
  }
}

console.log("Build check OK:", required.length, "paths present.");

import { execSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
process.chdir(__dirname);
const out = path.join(__dirname, "deploy-out.txt");
const lines = [];

function log(s) {
  lines.push(typeof s === "string" ? s : String(s));
}

function run(cmd) {
  log(`\n$ ${cmd}\n`);
  try {
    log(
      execSync(cmd, {
        encoding: "utf8",
        shell: true,
        stdio: ["ignore", "pipe", "pipe"],
        maxBuffer: 50 * 1024 * 1024,
      })
    );
  } catch (e) {
    if (e.stdout) log(e.stdout);
    if (e.stderr) log(e.stderr);
    log(`EXIT ${e.status ?? "?"}: ${e.message}`);
  }
}

run("cd");
run("dir");
run("git status");
run("git remote -v");
run("gh auth status");
if (!fs.existsSync(path.join(__dirname, ".git"))) {
  run("git init");
}
run("git add -A");
run('git commit -m "Live deploy"');
run("git branch -M main");
run("git remote remove origin");
run("git remote add origin https://github.com/saleh-b-90-hub/ucarsmotors-site.git");
