);
run(
  'powershell -NoProfile -Command "try { (Invoke-WebRequest -UseBasicParsing -Uri https://www.ucarsmotors.com/ -TimeoutSec 30).StatusCode } catch { $_.Exception.Message }"'
);

fs.writeFileSync(out, lines.join(""), "utf8");

